local SpiceGrinderMaker = {}
local PRODUCTS = {
    iron_spicegrinder = { name = "Železni mlinček za začimbe", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni mlinček za začimbe za kuhinjo." },
    bronze_spicegrinder = { name = "Bronast mlinček za začimbe", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast mlinček za začimbe za kuhinjo." },
    silver_spicegrinder = { name = "Srebrn mlinček za začimbe", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn mlinček za začimbe za kuhinjo." },
    gilded_spicegrinder = { name = "Pozlačen mlinček za začimbe", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen mlinček za začimbe za kuhinjo." },
    jewel_set_spicegrinder = { name = "Draguljast mlinček za začimbe", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast mlinček za začimbe za kuhinjo." },
    royal_sovereign_spicegrinder = { name = "Kraljevski suveren mlinček za začimbe", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren mlinček za začimbe z biseri za krono." },
}
local BUILDINGS = {
    spicegrinder_workshop = { name = "Spicegrinder delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    spicegrinder_house = { name = "Spicegrinder hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_spicegrinder_atelier = { name = "Mojstrski spicegrinder atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_spicegrinder_palace = { name = "Suverena spicegrinder palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SpiceGrinderMaker.ironStock = 16; SpiceGrinderMaker.bronzeStock = 14; SpiceGrinderMaker.woodStock = 10; SpiceGrinderMaker.leatherStock = 8; SpiceGrinderMaker.silverStock = 8; SpiceGrinderMaker.goldStock = 6; SpiceGrinderMaker.jewelStock = 4; SpiceGrinderMaker.pearlStock = 4
SpiceGrinderMaker.productStock = {}; SpiceGrinderMaker.buildings = {}; SpiceGrinderMaker.maker = nil; SpiceGrinderMaker.activeMaking = {}; SpiceGrinderMaker.totalProducts = 0; SpiceGrinderMaker.dayTimer = 0
function SpiceGrinderMaker.init() SpiceGrinderMaker.ironStock=16; SpiceGrinderMaker.bronzeStock=14; SpiceGrinderMaker.woodStock=10; SpiceGrinderMaker.leatherStock=8; SpiceGrinderMaker.silverStock=8; SpiceGrinderMaker.goldStock=6; SpiceGrinderMaker.jewelStock=4; SpiceGrinderMaker.pearlStock=4; SpiceGrinderMaker.productStock={}; SpiceGrinderMaker.buildings={}; SpiceGrinderMaker.maker=nil; SpiceGrinderMaker.activeMaking={}; SpiceGrinderMaker.totalProducts=0; SpiceGrinderMaker.dayTimer=0; print("[SpiceGrinderMaker] Royal Spice Grinder Maker System initialized (6 products, 4 buildings)") end
function SpiceGrinderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SpiceGrinderMaker.maker={name=n or ("Mlinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mlinar najet: %s (spretnost: %d)",SpiceGrinderMaker.maker.name,s),"success") end; return true end
function SpiceGrinderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SpiceGrinderMaker.build(id) local ok,e=SpiceGrinderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SpiceGrinderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SpiceGrinderMaker.getQualityBonus() local b=0; for _,bd in ipairs(SpiceGrinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SpiceGrinderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SpiceGrinderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SpiceGrinderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SpiceGrinderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SpiceGrinderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SpiceGrinderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SpiceGrinderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SpiceGrinderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SpiceGrinderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SpiceGrinderMaker.buildings==0 then return false,"Potrebna mlinčna delavnica" end; if not SpiceGrinderMaker.maker then return false,"Potreben mlinar" end; return true end
function SpiceGrinderMaker.make(pt,qty) qty=qty or 1; local ok,e=SpiceGrinderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SpiceGrinderMaker.ironStock=SpiceGrinderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SpiceGrinderMaker.bronzeStock=SpiceGrinderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SpiceGrinderMaker.woodStock=SpiceGrinderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SpiceGrinderMaker.leatherStock=SpiceGrinderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SpiceGrinderMaker.silverStock=SpiceGrinderMaker.silverStock-d.silverCost*qty end; if d.goldCost then SpiceGrinderMaker.goldStock=SpiceGrinderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SpiceGrinderMaker.jewelStock=SpiceGrinderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SpiceGrinderMaker.pearlStock=SpiceGrinderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SpiceGrinderMaker.maker then t=math.max(1,t-math.floor(SpiceGrinderMaker.maker.skill/13)) end; table.insert(SpiceGrinderMaker.activeMaking,{id="spicegrinder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SpiceGrinderMaker.completeMaking(m) local q=1.0+(SpiceGrinderMaker.getQualityBonus()/100); if SpiceGrinderMaker.maker then q=q+(SpiceGrinderMaker.maker.skill/140) end; q=math.min(2.5,q); SpiceGrinderMaker.productStock[m.productType]=(SpiceGrinderMaker.productStock[m.productType] or 0)+m.quantity; SpiceGrinderMaker.totalProducts=SpiceGrinderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SpiceGrinderMaker.maker then SpiceGrinderMaker.maker.itemsMade=SpiceGrinderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SpiceGrinderMaker.maker.skill=math.min(100,SpiceGrinderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mlinček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"spicegrinder.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SpiceGrinderMaker.update(dt) if not _G.state then return end; SpiceGrinderMaker.dayTimer=SpiceGrinderMaker.dayTimer+dt; if SpiceGrinderMaker.dayTimer>=30 then SpiceGrinderMaker.dayTimer=0; for i=#SpiceGrinderMaker.activeMaking,1,-1 do local m=SpiceGrinderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SpiceGrinderMaker.completeMaking(m); table.remove(SpiceGrinderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SpiceGrinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SpiceGrinderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SpiceGrinderMaker.getStats() return {ironStock=SpiceGrinderMaker.ironStock,bronzeStock=SpiceGrinderMaker.bronzeStock,woodStock=SpiceGrinderMaker.woodStock,leatherStock=SpiceGrinderMaker.leatherStock,silverStock=SpiceGrinderMaker.silverStock,goldStock=SpiceGrinderMaker.goldStock,jewelStock=SpiceGrinderMaker.jewelStock,pearlStock=SpiceGrinderMaker.pearlStock,productStock=SpiceGrinderMaker.productStock,numBuildings=#SpiceGrinderMaker.buildings,hasMaker=SpiceGrinderMaker.maker~=nil,makerName=SpiceGrinderMaker.maker and SpiceGrinderMaker.maker.name or "—",makerSkill=SpiceGrinderMaker.maker and SpiceGrinderMaker.maker.skill or 0,activeMaking=#SpiceGrinderMaker.activeMaking,totalProducts=SpiceGrinderMaker.totalProducts} end
return SpiceGrinderMaker
